#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────



# Deploy A of docs/PYTHON_312_PLAN.md: production Judge0 (server and workers) moves to our own
# image, which adds Python 3.12 as language 100 next to 3.8.1 (71). CodeBite keeps sending 71, so
# users see no change. Done by hand at low traffic, not by a push: a normal deploy would restart
# Judge0 at an unplanned moment, at the end of a backend roll.
#
# Run from the repo root on master, with the image swap committed:  scripts/cutover-judge0-py312.sh
# SSH_TARGET defaults to mini. Re-running is safe: each stage checks before it acts.

SSH_TARGET=${SSH_TARGET:-mini}
IMAGE=localhost/codebite-judge0:1.13.1-py312
OLD_IMAGE=judge0/judge0:1.13.1
COMPOSE_FILE=infra/docker-compose.prod.yml
COMPOSE="docker compose -f $COMPOSE_FILE"
SITE_URL="https://code-bite.com/problems"

# names_image_twice: the compose text on stdin names $IMAGE for both Judge0 services.
names_image_twice() {
  [[ "$(grep -cF "image: $IMAGE")" == 2 ]]
}

# on_server CMD runs CMD in the server's checkout.
on_server() {
  ssh -o BatchMode=yes -o ConnectTimeout=10 "$SSH_TARGET" "cd ~/CodeBite && $1"
}

# language_ids prints the ids production Judge0 lists on /languages, one per line.
language_ids() {
  on_server "curl -sf --max-time 10 http://localhost:2358/languages" 2>/dev/null \
    | grep -o '"id":[0-9]*' | cut -d: -f2
}

# lists_both_pythons: /languages has both 71 (3.8.1) and 100 (3.12).
lists_both_pythons() {
  local ids; ids=$(language_ids) || return 1
  grep -qx 71 <<< "$ids" && grep -qx 100 <<< "$ids"
}

# judges_python ID runs print(6*7) as language ID on production Judge0 and succeeds when it prints
# 42. It goes through a worker, so it checks the workers' Python binary, not just the server's row.
judges_python() {
  on_server "bash -s" <<EOF
set -euo pipefail
token=\$(curl -sf --max-time 10 -X POST -H 'Content-Type: application/json' \
  -d '{"source_code":"print(6*7)","language_id":$1}' \
  'http://localhost:2358/submissions?base64_encoded=false' | grep -o '"token":"[^"]*"' | cut -d'"' -f4)
for _ in \$(seq 1 30); do
  r=\$(curl -sf --max-time 10 "http://localhost:2358/submissions/\$token?base64_encoded=false&fields=stdout,status_id")
  case "\$r" in *'"status_id":1,'*|*'"status_id":2,'*|*'"status_id":1}'*|*'"status_id":2}'*) sleep 2 ;; *) break ;; esac
done
echo "\$r"
grep -qF '"stdout":"42\n"' <<< "\$r"
EOF
}

# roll_back puts both Judge0 containers back on the stock image through a compose override kept
# outside the checkout, so the server's working tree stays clean for the next deploy.
roll_back() {
  on_server "cat > ~/judge0-rollback.yml <<'EOF'
services:
  judge0:
    image: $OLD_IMAGE
    pull_policy: missing
  judge0-workers:
    image: $OLD_IMAGE
    pull_policy: missing
EOF
$COMPOSE -f ~/judge0-rollback.yml up -d --no-deps judge0 judge0-workers" \
    || warn "the rollback failed too; see: ssh $SSH_TARGET docker logs codebite-judge0"
  SKIPPED+=("Judge0 is back on $OLD_IMAGE, but master still names $IMAGE: revert the swap on master with [skip ci] before the next deploy, which would put the new image back")
}

run_wizard() {

TOTAL_STAGES=6
RESULTS=()
record() {
  if confirm "$1"; then RESULTS+=("PASS  $1"); else RESULTS+=("FAIL  $1"); SKIPPED+=("investigate: $1"); fi
}

banner "CodeBite: production Judge0 onto the Python 3.12 image (deploy A)"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Preflight"
[[ -f "$COMPOSE_FILE" ]] || { warn "run this from the repo root"; exit 1; }
until on_server "true"; do
  warn "can't reach ~/CodeBite over ssh $SSH_TARGET"
  ask SSH_TARGET "SSH target for the server (user@host or an ~/.ssh/config alias):"
done
note "reached ~/CodeBite on $SSH_TARGET"
if ! on_server "docker image inspect -f '{{.Created}}' $IMAGE" >/dev/null 2>&1; then
  warn "$IMAGE is not on $SSH_TARGET. Build it first: scripts/build-judge0-image.sh"
  exit 1
fi
note "$IMAGE is on $SSH_TARGET"
if on_server "docker image inspect $OLD_IMAGE" >/dev/null 2>&1; then
  note "$OLD_IMAGE is still there too, for a rollback"
else
  warn "$OLD_IMAGE is gone from $SSH_TARGET, so a rollback would have to pull it from Docker Hub"
  confirm "Go on anyway?" || exit 1
fi
current=$(on_server "docker inspect -f '{{.Config.Image}}' codebite-judge0 codebite-judge0-workers" | sort -u || true)
note "Judge0 containers run: $(tr '\n' ' ' <<< "$current")"
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "The image swap is on master, with [skip ci]"
git fetch -q origin master
if names_image_twice <<< "$(git show origin/master:"$COMPOSE_FILE")"; then
  note "origin/master already names $IMAGE"
  if ! grep -qF '[skip ci]' <<< "$(git log -1 --format=%B "$(git log -1 --format=%H origin/master -- "$COMPOSE_FILE")")"; then
    warn "the commit that put it there has no [skip ci], so a deploy may already have restarted Judge0 (see stage 1)"
  fi
else
  if [[ "$(git rev-parse --abbrev-ref HEAD)" != master ]] || ! names_image_twice < "$COMPOSE_FILE" \
      || ! git diff --quiet HEAD -- "$COMPOSE_FILE"; then
    warn "commit the swap of $COMPOSE_FILE (both Judge0 services on $IMAGE, pull_policy: never) on master first"
    exit 1
  fi
  say "These commits go to origin/master:"
  git log --oneline origin/master..HEAD | while IFS= read -r line; do note "  $line"; done
  if ! grep -qF '[skip ci]' <<< "$(git log -1 --format=%B HEAD)"; then
    warn "the last commit has no [skip ci], so pushing would run deploy.yml and restart Judge0 mid-roll"
    note "amend its message, or add: git commit --allow-empty -m 'chore: deploy A [skip ci]'"
    exit 1
  fi
  note "GitHub skips deploy.yml for a push whose last commit says [skip ci], so none of these deploy"
  confirm "Push them to origin/master now?" || exit 1
  git push origin HEAD:master
fi
warn "until this cutover is finished, don't push or merge anything else to master:"
note "  any deploy ends with 'docker compose up -d', which would restart Judge0 on the new image."
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Pull master on $SSH_TARGET"
say "Pulling first keeps the server's checkout clean: a local edit to the compose file"
say "would make the next deploy's git pull fail. Nothing restarts in this stage."
dirty=$(on_server "git status --porcelain --untracked-files=no")
if [[ -n "$dirty" ]]; then
  warn "the server's checkout has local changes; clean them up first:"
  while IFS= read -r line; do note "  $line"; done <<< "$dirty"
  exit 1
fi
if [[ "$(on_server "git symbolic-ref -q --short HEAD" || true)" != master ]]; then
  warn "the server's checkout isn't on master (a deploy rollback leaves it detached)"
  note "put it back first: ssh $SSH_TARGET 'cd ~/CodeBite && git checkout master'"
  exit 1
fi
on_server "git pull --ff-only -q origin master"
names_image_twice <<< "$(on_server "cat $COMPOSE_FILE")" \
  || { warn "the server's $COMPOSE_FILE doesn't name $IMAGE for both Judge0 services"; exit 1; }
note "the server is at $(on_server "git log -1 --oneline")"
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Restart Judge0 on the new image"
say "This recreates only codebite-judge0 and codebite-judge0-workers. Its database and Redis,"
say "the backend and the worker keep running. Submissions judged during the restart may fail."
traffic=$(on_server "docker exec -i codebite-postgres sh -c 'psql -U \"\$POSTGRES_USER\" -d codebite -tA'" \
  <<< "select count(*) filter (where status = 'PENDING') || ' pending, latest at ' || coalesce(max(created_at)::text, 'never') from submissions" \
  || echo "unknown (couldn't query codebite-postgres)")
note "submissions right now: $traffic"
if ! confirm "Restart production Judge0 on $IMAGE now?"; then
  warn "not restarted. The server already has the new compose file, so the next deploy would restart it"
  SKIPPED+=("restart Judge0: re-run this wizard at low traffic")
  finish; exit 1
fi
on_server "$COMPOSE up -d --no-deps judge0 judge0-workers"
note "now running: $(on_server "docker inspect -f '{{.Name}} {{.Config.Image}}' codebite-judge0 codebite-judge0-workers" | tr '\n' ' ')"
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Check Judge0"
say "The server reseeds its languages on every start; waiting for /languages to list 71 and 100."
up=false
for _ in $(seq 1 36); do
  if lists_both_pythons; then up=true; break; fi
  printf '.'; sleep 5
done
printf '\n'
healthy=false
if $up; then
  note "/languages lists 71 and 100"
  RESULTS+=("PASS  /languages lists 71 and 100")
  if judges_python 71 >/dev/null && judges_python 100 >/dev/null; then
    note "print(6*7) gives 42 on both 71 and 100"
    RESULTS+=("PASS  a worker runs Python on 71 and 100")
    healthy=true
  else
    warn "a worker didn't print 42 on 71 or 100; see: ssh $SSH_TARGET docker logs codebite-judge0-workers"
    RESULTS+=("FAIL  a worker runs Python on 71 and 100")
  fi
else
  warn "after 3 minutes /languages still doesn't list both 71 and 100 (ids: $(language_ids | tr '\n' ' '))"
  note "see: ssh $SSH_TARGET docker logs codebite-judge0"
  RESULTS+=("FAIL  /languages lists 71 and 100")
fi
if ! $healthy && confirm "Roll Judge0 back to $OLD_IMAGE?"; then
  roll_back
  note "rolled back; /languages ids: $(language_ids | tr '\n' ' ')"
fi
pause

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Python on the site, and the server's checkout"
if $healthy; then
  open_url "$SITE_URL"
  step "Open any problem, pick Python, and Submit a correct solution (CodeBite still sends id 71)"
  record "The Python submission is Accepted"
fi
git fetch -q origin master
server_head=$(on_server "git rev-parse HEAD")
if [[ "$server_head" == "$(git rev-parse origin/master)" && -z "$(on_server "git status --porcelain --untracked-files=no")" ]]; then
  RESULTS+=("PASS  the server's checkout matches origin/master and is clean")
else
  RESULTS+=("FAIL  the server's checkout matches origin/master and is clean")
  SKIPPED+=("make ~/CodeBite on $SSH_TARGET match master, or the next deploy's git pull fails")
fi

finish
say "Results:"
for r in "${RESULTS[@]}"; do note "  $r"; done
say "Next: the replay on id 100 (plan step 4), then deploy B switches CodeBite to id 100."
printf '\n'
}

run_wizard "$@"; exit
